// SRM0 with an exponential membrane filter and an exponential after-spike kernel
function srmStep(state, I, t, dt, p) {
  state.h += (dt / p.tau) * (-state.h + p.R * I);      // kappa * I as a running filter
  let u = p.uRest + state.h;
  for (const tf of state.spikes) u -= p.eta0 * Math.exp(-(t - tf) / p.tauEta);
  if (u >= p.theta) state.spikes.push(t);               // no reset: eta does the work
  return u;
}
